		m := manifestFromRecord(existing)
		report.Manifest = &m
		if sameApplication(existing, req.ProcessedOn, seen) {
			report.Status = CheckReplayable
		} else {
			report.Status = CheckConflict
		}
		return nil
	}

	// 申请编号已被任意一条成功的期限修订占用：编号占用属于整个保管库，
